# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
P=[['拉丁 per- + suadere → persuadere','充分、加强 + 劝说 → 说服'],['法语 persuader → 英语 persuade','让人接受看法或愿意采取行动']]
A=[['拉丁 persuadere 的分词词干 persuas- → 中世纪拉丁 persuasivus','说服 → 能说服人的'],['法语 persuasif → 英语 persuasive','有说服力的']]
D=[['拉丁 dis- + suadere → dissuadere','朝相反方向劝说 → 劝阻'],['法语 dissuader／拉丁形式 → 英语 dissuade','劝某人不要做某事']]
W=[
E('persuade','英 /pəˈsweɪd/；美 /pərˈsweɪd/','说服；使相信；劝动','你原本没打算这样想或这样做，听完之后改了主意。','拉丁 per- 加强 + suadere 劝说，形成 persuadere，经法语 persuader 进入英语。核心是通过表达让人转变态度。',P,'persuade someone to do something 是把人劝动，让他愿意去做；persuade someone that… 是让他相信某个判断。I tried to persuade him 只说我努力劝了，不保证成功；I persuaded him to stay 通常表示他真的留下了。','persuade somebody to do something；persuade somebody that…；persuade somebody of something。','convince 与 persuade 有重叠，不能硬说前者只能说信念、后者只能说行动。学会具体句型更有用：persuade somebody to do 是非常常见的搭配。',('We persuaded her to join us for dinner.','我们说服她和我们一起吃晚饭。'),('The evidence persuaded me that the earlier estimate was wrong.','这些证据让我相信，之前的估计有误。'),sources=['https://www.etymonline.com/word/persuade','https://www.oxfordlearnersdictionaries.com/definition/english/persuade']),
E('persuasion','英 /pəˈsweɪʒən/；美 /pərˈsweɪʒən/','说服；劝说；信仰或主张','用理由慢慢把人的想法推向另一边；也可以指一个人已经相信的一套主张。','由拉丁 persuasio 经古法语或直接借入，来自 persuadere 的分词词干。英语名词早于英语动词 persuade，不是后来才在动词后面加尾巴。',[['拉丁 persuadere → persuasio','说服 → 说服这件事'],['古法语 persuasion／拉丁名词 → 英语 persuasion','劝说；后来也指信念、信仰或主张']],'It took some persuasion 表示需要费一点口舌才劝动。people of different political persuasions 则是在说不同政治立场的人，不是他们用了不同说服技巧。先看语境是在谈劝的过程，还是相信的内容。','gentle persuasion；powers of persuasion；political or religious persuasion。','persuasion 通常靠理由、情感或表达争取认同；coercion 是强迫。它们都可能改变行为，但对方是否被迫是重要区别。',('After some gentle persuasion, he agreed to take a break.','经过一番温和劝说，他同意休息一下。'),('The discussion included people of several political persuasions.','讨论中有持不同政治主张的人参加。'),sources=['https://www.etymonline.com/word/persuasion','https://www.oxfordlearnersdictionaries.com/definition/english/persuasion']),
E('persuasive','英 /pəˈsweɪsɪv/；美 /pərˈsweɪsɪv/','有说服力的；善于说服人的','听完会觉得：这个理由站得住，我可能真的该重新考虑。','经法语 persuasif 来自中世纪拉丁 persuasivus，使用 persuadere 的 persuas- 分词词干。不是英语中把 persuade 的 d 随意换成 s。',A,'a persuasive argument 是有力到足以让人改变想法的论证。a persuasive speaker 则说这个人很会让别人接受观点。它评价说服效果，不自动保证内容真实：错误的信息有时也会被包装得很有说服力。','a persuasive argument；persuasive evidence；a persuasive speaker；a persuasive case for something。','plausible 是听起来像是真的；persuasive 更强调能让人接受。credible 侧重值得相信，三者不能在所有句子里互换。',('She made a persuasive case for extending the library’s opening hours.','她提出了很有说服力的理由，主张延长图书馆开放时间。'),('The presentation was persuasive because it addressed the audience’s main concerns.','这场演示很有说服力，因为它回应了听众最关心的问题。'),sources=['https://www.etymonline.com/word/persuasive','https://www.oxfordlearnersdictionaries.com/definition/english/persuasive']),
E('persuasively','英 /pəˈsweɪsɪvli/；美 /pərˈsweɪsɪvli/','有说服力地','不是只把观点大声说出来，而是用理由和组织方式让人愿意点头。','英语 persuasive + -ly，形成描述说话、论证和表达方式的副词。',A+[['英语 persuasive + -ly → persuasively','以能让人信服的方式']],'argue persuasively 是论证得有说服力，write persuasively 是写得让人信服。它并不要求声音有气势：安静、具体、抓住关键的解释也可以 persuasively。常与 argue、explain、write 连用。','argue persuasively for something；explain persuasively；write persuasively。','confidently 只说自信地，persuasively 说能打动别人接受。一个人可以非常自信，却拿不出有说服力的理由。',('He argued persuasively that the simpler design would be easier to maintain.','他有说服力地论证了，较简单的设计更容易维护。'),('The author writes persuasively about the value of public libraries.','作者把公共图书馆的价值讲得很有说服力。'),sources=['https://en.wiktionary.org/wiki/persuasively#English','https://www.oxfordlearnersdictionaries.com/definition/english/persuasively']),
E('unpersuasive','英 /ˌʌnpəˈsweɪsɪv/；美 /ˌʌnpərˈsweɪsɪv/','缺乏说服力的；不足以令人信服的','听完以后，我还是没有被打动：关键的疑问没有得到回答。','英语 un- 不 + persuasive 有说服力的，是英语内部的否定派生。',A+[['英语 un- + persuasive → unpersuasive','没有足够说服力的']],'an unpersuasive explanation 不一定每一句都是假的，可能只是证据不足、遗漏关键问题，或者推理没连起来。评论文章常用它来否定论证力度，比直接说 nonsense 更具体。','an unpersuasive argument；an unpersuasive explanation；find something unpersuasive。','unpersuaded 说人还没有被说服；unpersuasive 说理由或表达本身说服力不足。不要把主客体弄反。',('I found the explanation unpersuasive because it ignored the missing data.','我觉得这个解释缺乏说服力，因为它回避了数据缺失的问题。'),('The review called the film’s final twist clever but unpersuasive.','评论认为电影最后的转折很巧，却难以令人信服。'),sources=['https://www.etymonline.com/word/unpersuasive','https://dictionary.cambridge.org/us/dictionary/english/unpersuasive']),
E('dissuade','/dɪˈsweɪd/','劝阻；劝退','对方正准备往前走，你用理由让他改变主意，决定不走那一步。','拉丁 dis- 朝相反方向、离开 + suadere 劝说，形成 dissuadere，经法语或直接进入英语。这里是把人从某个行动上劝开。',D,'dissuade someone from doing something 是劝某人别做。from 后面接名词或 -ing：dissuade him from leaving。它通常强调通过劝说改变打算；暴雨让人打消出门念头，也能作引申用法。','dissuade somebody from doing something；try to dissuade somebody；nothing could dissuade her。','persuade someone to go 是劝去，dissuade someone from going 是劝别去。deter 可以靠风险、障碍或惩罚阻止，不一定通过谈话。',('We tried to dissuade him from sending the angry email.','我们试着劝他不要发送那封愤怒的邮件。'),('Her friends could not dissuade her from applying for the demanding role.','朋友们没能劝她放弃申请那个要求很高的职位。'),sources=['https://www.etymonline.com/word/dissuade','https://www.oxfordlearnersdictionaries.com/definition/english/dissuade']),
E('dissuasion','/dɪˈsweɪʒən/','劝阻；规劝不要做某事','把别做这件事的劝告和努力，作为一个过程来谈。','拉丁 dissuasio 来自 dissuadere 的分词词干，经法语 dissuasion 或直接借入。英语名词比 dissuade 更早出现，是独立借入的名词支线。',[['拉丁 dissuadere → dissuasio','劝不要做 → 劝阻、反对的劝告'],['法语 dissuasion／拉丁名词 → 英语 dissuasion','劝阻的行为或过程']],'dissuasion 是 dissuade 的名词对应，偏正式，比动词少见。attempts at dissuasion 就是种种劝阻的努力。日常通常直接说 tried to dissuade her，更自然；阅读时认出它是在说劝退即可。','attempts at dissuasion；gentle dissuasion；resist dissuasion。','persuasion 通常往接受某事的方向劝；dissuasion 则往放弃某事的方向劝。它不是未能说服，而是劝说的目标相反。',('Despite several attempts at dissuasion, she continued with the project.','尽管有人多次劝阻，她还是继续了这个项目。'),('Gentle dissuasion worked better than an angry command.','温和劝阻比愤怒的命令更有效。'),sources=['https://www.etymonline.com/word/dissuasion','https://en.wiktionary.org/wiki/dissuasion#English'])]
ROOT=dict(id='C1445',meaning='劝说；使人接受',core='SUAD / SUAS = PERSUADE',image='把一个人的想法往某个方向劝动：可以劝他去，也可以劝他别去。',intro='拉丁 suadere 表示劝告、劝说，per- 加强后形成 persuadere，dis- 改变方向后形成 dissuadere。更远可联系表示甜、令人愉快的印欧词根：让某个选择显得值得接受；这不意味着所有说服都是甜言蜜语。',forms='suad- 与 suas- 是历史词干变化：persuade 用前者，persuasion、persuasive 关联拉丁分词词干 persuas-。名词 persuasion、dissuasion 各自借入，不能按现代词形倒画历史。',branches=[['把人劝动','persuade, persuasion'],['理由是否有力量','persuasive, persuasively, unpersuasive'],['劝不要做','dissuade, dissuasion']],contrasts='说服、强迫、吓住并不相同。学这组最先掌握两个句型：persuade somebody to do；dissuade somebody from doing。',practice='She persuaded me to wait and dissuaded me from making a rushed decision.\n\n她劝我再等等，也劝我不要仓促作决定。',words=[x['word'] for x in W],exclude={})
if __name__=='__main__':
 for name,data in [('roots_suad',[ROOT]),('words_suad',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 data=[]
 for w in W:
  if w['word'] in ['unpersuasive','dissuasion']:data.append(dict(word=w['word'],pos='adj' if w['word']=='unpersuasive' else 'noun',ipa=w['ipa'],gloss={'unpersuasive':'Not convincing.','dissuasion':'The act of advising someone not to do something.'}[w['word']],meaning_zh=w['meaning'],etymology_text={'unpersuasive':'English un- + persuasive.','dissuasion':'From French dissuasion or Latin dissuasio, from dissuadere.'}[w['word']],sources=w['sources']))
 Path('.cache/batch200/root_suad_supplement_request.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
